FuncDef.Code:
float opSmoothInfRepeatXYZ(inout vec3 p, float spacingX, float spacingY, float spacingZ, float smoothnessX, float smoothnessY, float smoothnessZ)
{
    vec3 spacing = vec3(spacingX, spacingY, spacingZ);
    vec3 smoothness = vec3(smoothnessX, smoothnessY, smoothnessZ);
    vec3 halfsize = spacing*0.5;
    vec3 c = floor((p + halfsize)/spacing);
    float cellIndex = c.x + c.y + c.z + PI * sin(c.x * c.y * c.z);
    p = modEx(p + halfsize, spacing, smoothness) - halfsize;

    return cellIndex;
}
